Let $\hat g(s)$ be   the Laplace
transform of a function $g(t)$ so that
\begin{equation}  g(t) =\frac{1}{2\pi i}
\int_{c-i\infty}^{c+i\infty} e^{ st} \hat g(s)  d  s,\ c>0. \end{equation}

Then,    Eqs.  (\ref{re}) and (\ref{repp}) allow  to  recover the
  distribution of $E_r$ in closed form via
\begin{subequations} \begin{eqnarray}


\hat m(s)&=&\frac{1}{s} \frac{\hat\psi(s)}{1-\hat \psi(s)}, \\   
\hat \phi(s|r)&=&  e^{s  r } \left[1-\hat \psi(s)\right] \int_r^\infty e^{-sl} \hat m(l)l d  l, 
\end{eqnarray}
\end{subequations}

where   $ \hat m(s) $ and $  \hat \phi(s|r)$ are the Laplace transforms of  $m(t)$  and $\phi(t|r) \equiv \partial_t \Phi(t|r)$.

Let $\mu\equiv~\mathbb{E}[\tau_{n+1}]$, $\mu_r\equiv~\mathbb{E}[E_{r}]$; then, using   that $  \hat{\psi}(s v )=1-\mu sv
+O(v^2)$ and so forth we see that for  small $v$, $\hat{ J}(s|r)$
has an expansion in powers of $v$ as
 \begin{equation}
\hat{J}(s|r) =  \hat{\mathbb{F}}(s) - \frac{\mu-\mu_r}{s}  -    \frac{
\hat{h}(s) }{ 1- \hat{h}(s) }   (\mu-\mu_r)\mu  v + O(v^2),
\end{equation}
which implies, in particular, Eq.~(\ref{v=0}).

We  illustrate the ideas above by detailing the case when jump magnitudes
  have
an exponential distribution
  $h(u)=\gamma e^{-\gamma u}$, where $\gamma>0$ is a real parameter, and  sojourn times
 an Erlang distribution $\tau_n\sim\mathcal Er(\lambda,2)$.
Hence
\begin{equation}

\hat{h}(s)= \frac{\gamma}{\gamma +s},\quad  \hat{\psi}(s)  = \frac{\lambda^2}{(\lambda +s)^2}. \end{equation}
In this case Eq.~(\ref{FF_eq})  yields that $\hat{\mathbb{F}}(s)$ is the
following rational function
 \begin{equation}
\hat{\mathbb{F}}(s)=\frac{1}{v s^2}\frac{2\lambda \gamma v+ v(2 \lambda
+\gamma v) s + v^2 s^2}{\lambda (\lambda + 2\gamma v) + v(2
\lambda +\gamma v) s+v^2 s^2}.
 \end{equation}
 Hence, the mean  escape  time of $(0,b)$ after a jump is
  \begin{eqnarray}
  \mathbb{T}_b(x)= \frac{2 \gamma v}{\lambda + 2 \gamma v} \varrho \nonumber\\
+\frac{\lambda^2}{z_+-z_-}\left[\frac{1-e^{-z_- \varrho}}{z_-^2}-\frac{1-e^{-z_+
\varrho}}{z_+^2}\right],
\end{eqnarray}
where we recall that $v \varrho=b-x$ is   the  initial
      distance to the boundary $b$
  and
\begin{equation}
z_{\pm}\equiv
 \lambda +\frac{\gamma v}{2}\left(1\pm\sqrt{1-\frac{4\lambda}{\gamma
v}}\right),
\end{equation}
with $\mbox{Re}[z_{\pm}]>0$.

The evaluation of  the mean exit time  starting at $r$,
$T_b(x,r)$, involves the renewal function and excess-life
distribution. We first obtain    from     Eq.~(\ref{hat_phi})
\begin{equation}
\hat m(s)=\frac{\lambda^2}{s^2(2\lambda +s)}, \quad  \hat
\phi(s|r)=\hat \psi(s)+ \frac{  (1-e^{-2 \lambda r})s\lambda }{ 2
(\lambda +s)^2}.
\end{equation}
By inversion we get $m(t)=  \big(2 \lambda t + e^{-2 \lambda
t}-1\big)/4$ and
\begin{equation}  \ \Phi(t|r)  
=
1-e^{-\lambda t} \left[ 1+  \left(\frac{ 1+{e^{-2 \lambda r
}}}{2}\right)\lambda t \right].
\end{equation}
Then by using  Eq.~(\ref{hattime})  we find at last that
\begin{eqnarray}  T_b(x,r) =\mathbb{T}_b(x) \nonumber 
\\
-  \frac{\lambda}{2}\frac{1-e^{-2\lambda r}}{z_+-z_-}\left[\frac{1-e^{-z_- \varrho}}{z_-}-\frac{1-e^{-z_+ \varrho}}{z_+}\right].
\end{eqnarray}
Plots of this function in terms of $x$ are given in Fig.~\ref{E2_up} for several values of $r$ and a certain choice of the rest of parameters.

\begin{figure}[htb]
{
\includegraphics[width=0.45\textwidth,keepaspectratio=true]{Fig1.eps}
} \caption{(Color online)  Sample representations of $T_b(x,r)$ for different values of $r$: $r=0$, i.e. $\mathbb{T}_b(x)$, solid (black) line, $r=0.4$,  dashed (red) line and $r=10.0$, dot-dashed (blue) line. The rest of the parameters were chosen as follows: $b=1.0$, $v=0.1$, $\lambda=1.0$ and $\gamma=0.1$.} \end{figure}

Finally note how, in particular,  if $v=0$     then  
\begin{eqnarray}
\mathbb{T}_b(x)=\frac{2}{\lambda}\left[1+\gamma (b-x)\right] &=&  \mathbb{E}[\tau_n]
\left(1+   \frac{b-x}{\mathbb{E}[J_n]}\right), \\
T_{b}(x,r)&=&\mathbb{T}_b(x)
 -\frac{1- e^{-2\lambda  r}}{2\lambda}.\end{eqnarray}

Further progress can be made for Erlang times, $\mathcal Er(\lambda,2)$. 
Indeed, in this case (\ref{TTb_down}) reads
\begin{eqnarray}
\mathbb{T}_b(x)= \frac{2-\left(2+\lambda \varrho\right)e^{-\lambda
\varrho}}{\lambda} \nonumber \\+\frac{\lambda^2}{v^2} \int^{b}_{x}
\left(z-x\right)e^{-\lambda \left(z-x\right)/v} \int^{z}_{0} h(u)
\mathbb{T}_b\left(z-u\right)d  ud  z,
\end{eqnarray}
 and hence, by differentiation we find that
$ \mathbb{T}_b(x)$, for $0< x< b$,  also satisfies the following
integral-differential equation:
\begin{eqnarray}
\mathbb{T}_b''(x)-\frac{2\lambda}{v}\mathbb{T}_b'(x)+\frac{\lambda^2}{v^2}\mathbb{T}_b(x)=
\frac{2\lambda}{v^2} \nonumber \\+\frac{\lambda^2}{v^2}\int^{x}_{0}h(u) \mathbb{T}_b\left(x-u\right)d  u, \end{eqnarray}
subject to the following boundary conditions: 
\begin{equation}

\lim_{x\to b}\mathbb{T}_b(x)=0,\mbox{ and }\lim_{x\to b}\mathbb{T}_b'(x)=-1/v. \end{equation}

\mathbb{T}_\infty(x)=\frac{2(1+\gamma x)}{\lambda-2 \gamma v}= \left(  1+\gamma
x  \right)\Big/\left( \frac{1}{ \Bbb E[\tau_n]}- \frac{v}{  \Bbb E[J_n]}
\right),

Skipping minor details
we obtain that $\mathbb{T}_b(x)$ and $T_b(x,r)$ satisfy respectively
\begin{eqnarray}
T_b(x,r)=
\int^{\varrho}_{0}\left[1-\Phi\left(l|r\right)\right]d  l \nonumber \\+
\frac{1}{v}\int^{b}_{x}
\phi\left(\left.\frac{z-x}{v}\right|r\right) \int^{b-z}_{-z} h(u)
\mathbb{T}_b\left(z+u\right)d  ud  z, 
\end{eqnarray}
and
\begin{eqnarray}
\mathbb{T}_b(x)= \int^{\varrho}_{0}\left[1-\Psi\left(l\right)\right]d
l \nonumber \\+ \frac{1}{v}\int^{b}_{x} \psi\left(\frac{z-x}{v}\right)
\int^{b-z}_{-z} h(u) \mathbb{T}_b\left(z+u\right)dud  z.  
\end{eqnarray}

With the previous selection for $h(\cdot)$ and
$\psi(\cdot)$, Eq.~(\ref{h_hat}), and in terms of    $z=sv $ 
we find

    \begin{eqnarray}

\hat{\mathbb{F}}(s)=\frac{v}{z} \frac{2\lambda \gamma v  +  (2 \lambda+\gamma v ) z +  z^2}{p \lambda^2 \gamma v   + \lambda  (\lambda +2\gamma v  )  z+   (2 \lambda +\gamma v  )  z^2+z^3  }. \end{eqnarray}

To be more explicit, let us consider the case
\begin{equation}
h(u)=\frac{k}{2 \sqrt{\pi u^3}} e^{-\frac{k^2}{4 u}}\quad (u>0),
\end{equation}
so that,
\begin{equation}
\hat h(s)=e^{-k \sqrt{s}}\sim 1-k \sqrt{s} +o(\sqrt{s}).
\end{equation}
It is well known that for the CTRW process $S_t$, Eq.~(\ref{process}), the 
propagator 
$p(u,t)du\equiv\Pr\{u<S_t\leqslant u+du\}$ reads in the Laplace-Laplace domain
\begin{equation}
\hat p(s_1,s_2)=  \frac{1}{s_2}\frac{1-\hat{\psi}(s_2)}{1-\hat{\psi}(s_2)\hat{h}(s_1)}\sim\frac{\mu}{\mu s_2+k \sqrt{s_1}},
\end{equation}
as $s_{1,2}\to 0$. The continuum limit is recovered in this case by letting $\mu \to 0$, $k \to 0$ with $k/\mu \to K$ finite. The process arising after this limit fulfills the following fractional diffusion equation
\begin{equation}

\partial_t p(u,t) + K\ { }^{}_0 D_u^{\frac{1}{2}} p(u,t)=0, 
\end{equation}
where ${ }^{}_0 D_u^{\frac{1}{2}}$ is the Riemann-Liouville fractional operator of order $\frac{1}{2}$, and whose solution reads
\begin{equation}
p(u,t)=\frac{K t}{2 \sqrt{\pi u^3}} e^{-\frac{K^2 t^2}{4 u}}.
\end{equation}
Let us now define $\Pi_b(x,t)$ as the probability that the process $X_t$ has never touched $b$ when it started at $x< b$ at the initial time, i.e.  
\begin{equation}
\Pi_b(x,t)\equiv\Pr\{X_{t'}< b, 0\leqslant t' \leqslant t |X_0=x\}.
\end{equation}
In the present case, as $S_t$ is an increasing positive process and $v>0$, it can be computed by direct integration of $p(u,t)$: 
\begin{equation}
\Pi_b(x,t)=\int_0^{b-x-vt} p(u,t) du=\text{Erfc}\left(\frac{K^2 t^2}{2\sqrt{b-x-vt}}\right).
\end{equation}
Now one can obtain $\mathbb{T}_b(x)$ through
\begin{eqnarray}
&&\mathbb{T}_b(x)=\int_{0}^{\frac{b-x}{v}} t \partial_t\left[1- \Pi_b(x,t)\right] dt=\int_{0}^{\frac{b-x}{v}} \Pi_b(x,t) dt\nonumber\\
&&=\frac{4v}{\sqrt{\pi}K^2}\int_0^{\infty}\left(\xi \sqrt{\xi^2+\frac{K^2(b-x)}{v^2}}-\xi^2\right) e^{-\xi^2}d\xi \nonumber \\
&&=\frac{2}{K}\sqrt{\frac{b-x}{\pi}}+ \frac{v}{K^2} \left[ e^{\frac{K^2(b-x)}{v^2}}\text{Erfc}\left(\frac{K}{v}\sqrt{b-x}\right)-1\right]. \nonumber \\ \end{eqnarray}



Alternatively, if we use the direct approach followed in this paper our results imply that the mean arrival time follows by inversion of the Laplace expression in
Eq.~(\ref{FF_sol}) 

when $\mu \to 0$, $k \to 0$ with $k/\mu \to K$ finite
\begin{equation}
\hat{\mathbb{F}}(s)=\frac{1}{v s^2}\frac{1-\hat{\psi}(s v)}{1-\hat{\psi}(s v)\hat{h}(s)} \rightarrow \frac{1}{vs^2 +Ks^{\frac{3}{2}}},
\end{equation}

that is \begin{equation}
\mathbb{T}_b(x)=\frac{1}{2\pi i}
\int_{c-i\infty}^{c+i\infty} \frac{e^{ s(b-x)} }{vs^2 +Ks^{\frac{3}{2}}} d s.
\end{equation}

Upon evaluation of this integral the result (\ref{Ex_TTb}) is recovered.

